import React from 'react';
import { useDrop } from 'react-dnd';
import { Link } from 'react-router-dom';
import { escapeHTML } from '../utils/security';

const FavouriteItem = ({ property, onRemove }) => {
  return (
    <div className="favourite-item">
      <div className="favourite-image">
        <img src={property.picture} alt={property.type} />
      </div>
      <div className="favourite-info">
        <h4 className="favourite-price">£{property.price.toLocaleString()}</h4>
        <p className="favourite-location">{escapeHTML(property.location)}</p>
        <p className="favourite-type">{property.type} · {property.bedrooms} bed</p>
      </div>
      <div className="favourite-actions">
        <Link to={`/property/${property.id}`} className="btn btn-small">
          View
        </Link>
        <button 
          className="btn-remove"
          onClick={() => onRemove(property.id)}
          aria-label="Remove from favourites"
        >
          ×
        </button>
      </div>
    </div>
  );
};

const FavouritesList = ({ favourites, properties, onRemoveFavourite, onClearFavourites }) => {
  const [, drop] = useDrop({
    accept: 'property',
    drop: () => ({ name: 'Favourites' }),
  });

  const favouriteProperties = properties.filter(p => favourites.includes(p.id));

  if (favouriteProperties.length === 0) {
    return (
      <div className="favourites-empty" ref={drop}>
        <h3>⭐ Favourites</h3>
        <p>Drag properties here or click the heart icon to add favourites</p>
        <div className="drop-zone">
          Drop properties here
        </div>
      </div>
    );
  }

  return (
    <div className="favourites-list" ref={drop}>
      <div className="favourites-header">
        <h3>⭐ Favourites ({favouriteProperties.length})</h3>
        <button 
          className="btn-clear"
          onClick={onClearFavourites}
          aria-label="Clear all favourites"
        >
          Clear All
        </button>
      </div>
      
      <div className="favourites-content">
        {favouriteProperties.map(property => (
          <FavouriteItem
            key={property.id}
            property={property}
            onRemove={onRemoveFavourite}
          />
        ))}
      </div>
      
      <div className="drop-hint">
        Drop properties here to add to favourites
      </div>
    </div>
  );
};

export default FavouritesList;
